/**
 * @suppress
 */
public object FfiConverterTypeCentwiseCore: FfiConverter<CentwiseCore, Pointer> {

    override fun lower(value: CentwiseCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): CentwiseCore {
        return CentwiseCore(value)
    }

    override fun read(buf: ByteBuffer): CentwiseCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: CentwiseCore) = 8UL

    override fun write(value: CentwiseCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



